/*!
 * Adminto Docs - App Initialization
 * Runs after layout.js has injected the shared chrome
 */
(function () {
    'use strict';

    /* --- Loading --- */
    function initLoading() {
        document.body.classList.remove('loading');
    }

    /* --- Dark Mode Toggle --- */
    function initDarkMode() {
        var toggle = document.getElementById('dark-mode-toggle');
        if (!toggle) return;

        // Check stored preference or system preference
        var stored = localStorage.getItem('adminto-docs-theme');
        var prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

        if (stored === 'dark' || (!stored && prefersDark)) {
            document.documentElement.classList.add('dark');
        }

        toggle.addEventListener('click', function () {
            var isDark = document.documentElement.classList.toggle('dark');
            localStorage.setItem('adminto-docs-theme', isDark ? 'dark' : 'light');
        });

        // Listen for system theme changes
        window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', function (e) {
            if (!localStorage.getItem('adminto-docs-theme')) {
                document.documentElement.classList.toggle('dark', e.matches);
            }
        });
    }

    /* --- Menu Toggle (Mobile) --- */
    function initMenuToggle() {
        var toggleBtn = document.querySelector('.button-menu-mobile');
        if (!toggleBtn) return;

        toggleBtn.addEventListener('click', function (e) {
            e.preventDefault();
            document.body.classList.toggle('sidebar-enable');
        });
    }

    /* --- Active Menu Highlight --- */
    function initActiveMenu() {
        var currentPath = window.location.pathname.split('/').pop() || 'index.html';
        var menuLinks = document.querySelectorAll('#side-menu li a');

        menuLinks.forEach(function (link) {
            if (link.getAttribute('href') === currentPath) {
                link.classList.add('active');
            }
        });
    }

    /* --- SimpleBar Init --- */
    function initSimpleBar() {
        if (typeof SimpleBar === 'undefined') return;
        var els = document.querySelectorAll('[data-simplebar]');
        els.forEach(function (el) {
            try { new SimpleBar(el); } catch (e) { el.style.overflowY = 'auto'; }
        });
    }

    /* --- Back to Top --- */
    function initBackToTop() {
        var btn = document.getElementById('back-to-top');
        if (!btn) return;

        var contentEl = document.querySelector('.content');

        function toggleVisibility() {
            var scrollTop = contentEl ? contentEl.scrollTop : window.scrollY;
            if (scrollTop > 400) {
                btn.classList.add('visible');
            } else {
                btn.classList.remove('visible');
            }
        }

        if (contentEl) {
            contentEl.addEventListener('scroll', toggleVisibility);
        } else {
            window.addEventListener('scroll', toggleVisibility);
        }

        btn.addEventListener('click', function () {
            if (contentEl) {
                contentEl.scrollTo({ top: 0, behavior: 'smooth' });
            } else {
                window.scrollTo({ top: 0, behavior: 'smooth' });
            }
        });
    }

    /* --- Keyboard Shortcuts --- */
    function initKeyboardShortcuts() {
        document.addEventListener('keydown', function (e) {
            // Don't trigger when typing in inputs
            var tag = e.target.tagName.toLowerCase();
            if (tag === 'input' || tag === 'textarea' || tag === 'select' || e.target.isContentEditable) return;

            var contentEl = document.querySelector('.content');

            switch (e.key) {
                case 'j':
                case 'ArrowDown':
                    if (contentEl) contentEl.scrollBy({ top: 100, behavior: 'smooth' });
                    break;
                case 'k':
                case 'ArrowUp':
                    if (contentEl) contentEl.scrollBy({ top: -100, behavior: 'smooth' });
                    break;
                case 't':
                    e.preventDefault();
                    if (contentEl) contentEl.scrollTo({ top: 0, behavior: 'smooth' });
                    break;
                default:
                    break;
            }
        });
    }

    /* --- Init --- */
    function init() {
        initLoading();
        initDarkMode();
        initMenuToggle();
        initActiveMenu();
        initSimpleBar();
        initBackToTop();
        initKeyboardShortcuts();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }
})();
